<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserMfaRecoveryCode\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Access\UserMfaRecoveryCode\Domain\ValueObject\UserMfaRecoveryCodeUserVO;
use Civi\Lughauth\Features\Access\User\Domain\UserRef;

trait UserMfaRecoveryCodeUserAccessor
{
    private UserMfaRecoveryCodeUserVO $_user;
    public function getUser(): UserRef
    {
        return $this->_user->value();
    }
    public function user(): UserMfaRecoveryCodeUserVO
    {
        return $this->_user;
    }
    public function isUserChanged(?self $original = null): bool
    {
        return !$this->_user->equals($original?->_user);
    }
    public function withUser(UserMfaRecoveryCodeUserVO|UserRef $user): self
    {
        $copy = clone $this;
        $copy->_user = UserMfaRecoveryCodeUserVO::from($user);
        return $copy;
    }
}
